// Centralized domain constants (BP-CONST-001 — no magic numbers in logic).
// Values that model Naano's real published mechanics are grouped and sourced.

export const SITE = {
  name: "Naano",
  tagline: "The B2B LinkedIn Creator Marketplace",
  description:
    "Find the creators your buyers already trust, launch campaigns in days, and track the clicks, leads and pipeline generated by every post.",
} as const;

// Homepage social-proof stats (mirrors the live marketing copy).
export const MARKETPLACE_STATS = {
  creators: "3,000+",
  countries: "100",
  impressions: "5M+",
  leads: "30K+",
  audienceMatch: "96%",
} as const;

// --- ICP taxonomy: shared across creator audience data + campaign targeting ---
export const AUDIENCE_FUNCTIONS = [
  "Founders",
  "Marketing",
  "Sales/BD",
  "Engineering/Data",
  "Product",
  "Finance/VC",
  "HR/People",
  "Operations",
] as const;

export const AUDIENCE_SENIORITIES = [
  "Founder/C-level",
  "VP/Head/Director",
  "Manager/Lead",
  "Senior IC",
] as const;

export const VERTICALS = [
  "B2B SaaS",
  "Fintech",
  "DevTools",
  "AI/ML",
  "Sales/Marketing",
  "HR/Future-of-work",
  "E-commerce",
  "Cybersecurity",
  "Data/Analytics",
] as const;

export type AudienceFunction = (typeof AUDIENCE_FUNCTIONS)[number];
export type AudienceSeniority = (typeof AUDIENCE_SENIORITIES)[number];
export type Vertical = (typeof VERTICALS)[number];

// --- Fit-score algorithm weights (deterministic ICP match, 0..100) ---
export const FIT_SCORE_WEIGHTS = {
  functionMatch: 0.45,
  seniorityMatch: 0.35,
  verticalMatch: 0.2,
  // Floor so an on-topic creator never shows an alarmingly low score.
  floor: 35,
} as const;

