export const CREATOR_WORTH = {
  euroPer1kFollowers: 12,
  floorPrice: 100,
  engagementBase: 0.6,
  engagementDivisor: 2.5,
  engagementCapMultiplier: 2,
  roundingStep: 10,
  nicheMultipliers: {
    "B2B SaaS": 1.2,
