  { label: "10–25K", maxFollowers: 25000, median: 312 },
  { label: "25–50K", maxFollowers: 50000, median: 480 },
  { label: "50K+", maxFollowers: Infinity, median: 720 },
] as const;

export const MIN_POST_PRICE = 20;
export const MAX_POST_PRICE = 5000;

