      "Everything in Self-Serve",
      "Campaign strategy & positioning",
      "Creator sourcing & coordination",
      "Brief creation & launch",
      "Reporting & optimisation",
    ],
  },
] as const;

// --- Pagination defaults (BP-PAGINATION-001) ---
export const PAGE_SIZE_DEFAULT = 24;
export const PAGE_SIZE_MAX = 100;

// --- Auth hardening (OWASP-AUTH-001 / RATELIMIT-001) ---
export const BCRYPT_ROUNDS = 12;
export const MAX_FAILED_LOGIN_ATTEMPTS_BEFORE_LOCKOUT = 5;
export const ACCOUNT_LOCKOUT_DURATION_MS = 15 * 60 * 1000; // 15 minutes

