import fs from "node:fs";
const PROJ = "/Users/raju/.claude/projects/-Users-raju-work-assignment-8x";
const MAIN = `${PROJ}/01244085-0729-497c-96c8-32499c3a8842.jsonl`;
const OUT = "/Users/raju/work/assignment-8x/.agent-logs";

// crude secret redaction for public safety
function redact(s){
  if(typeof s!=="string") return s;
  return s
    .replace(/sk-[A-Za-z0-9_-]{20,}/g,"[REDACTED_OPENAI_KEY]")
    .replace(/(AUTH_SECRET=)["']?[A-Za-z0-9+/=]{16,}["']?/g,"$1[REDACTED]");
}

const lines = fs.readFileSync(MAIN,"utf8").trim().split("\n");
let md = `# Agent session transcript (backfilled)\n\n`;
md += `Reconstructed from the Claude Code session transcript for the Naano clone build.\n`;
md += `Contains the user prompts, the agent's text responses, and a summary of each tool action.\n\n---\n\n`;
let turn=0, userPrompts=0, toolCalls=0, assistantMsgs=0;
for(const line of lines){
  let o; try{o=JSON.parse(line)}catch{continue}
  const role = o.message?.role || o.type;
  const content = o.message?.content;
  if(role==="user" && typeof content==="string"){
    // real user prompt (skip tool_result arrays)
    turn++; userPrompts++;
    md += `## ▸ User prompt (turn ${turn})\n\n${redact(content).trim()}\n\n`;
  } else if(role==="assistant" && Array.isArray(content)){
    assistantMsgs++;
    for(const b of content){
      if(b.type==="text" && b.text?.trim()){
        md += `### 🤖 Assistant\n\n${redact(b.text).trim()}\n\n`;
      } else if(b.type==="tool_use"){
        toolCalls++;
        const inp = JSON.stringify(b.input);
        const short = inp.length>300 ? inp.slice(0,300)+"…" : inp;
        md += `\`\`\`tool-call\n${b.name}(${redact(short)})\n\`\`\`\n\n`;
      }
    }
  }
}
fs.writeFileSync(`${OUT}/session-01-transcript.md`, md);
// copy raw jsonl (redacted line-wise) for full fidelity
const rawRedacted = lines.map(l=>redact(l)).join("\n");
fs.writeFileSync(`${OUT}/raw/session-01.jsonl`, rawRedacted);
// copy subagent logs
const subDir = `${PROJ}/01244085-0729-497c-96c8-32499c3a8842/subagents`;
let subCount=0;
if(fs.existsSync(subDir)){
  for(const f of fs.readdirSync(subDir)){
    if(f.endsWith(".jsonl")){ fs.writeFileSync(`${OUT}/raw/${f}`, redact(fs.readFileSync(`${subDir}/${f}`,"utf8"))); subCount++; }
  }
}
console.log(`transcript: ${userPrompts} user prompts, ${assistantMsgs} assistant messages, ${toolCalls} tool calls`);
console.log(`raw files: 1 main + ${subCount} subagents`);
console.log(`markdown size: ${(fs.statSync(`${OUT}/session-01-transcript.md`).size/1024).toFixed(0)}KB`);
EOF
